// Safely parses the Risk Assessor Agent's JSON output so downstream IFs read real fields
const raw = $json.output ?? $json.text ?? '';
const cleaned = raw.replace(/```json|```/g, '').trim();
let parsed, valid = true, error = null;
try { parsed = JSON.parse(cleaned); } catch (e) { valid = false; error = e.message; parsed = {}; }
return [{ json: {
  chatInput: $('N2: User Input').first().json.chatInput,
  sessionId: $('N2: User Input').first().json.sessionId,
  source: $('N2: User Input').first().json.source,
  ...parsed,
  _valid: valid,
  _parseError: error
} }];

// N16 no longer assigns risk_id itself — scanning for "the highest existing
// number" is exactly the kind of counting an LLM gets wrong, especially when its
// own search was entity-scoped (e.g. searching for a departing person's name)
// and never reliably surfaced the full register. N16 now only reports the
// existing_risk_ids it actually saw (a faithful extraction); this node computes
// the next sequential id(s) in real code and maps the rest of the fields onto
// the sheet's column names.
const existingIds = Array.isArray($json.existing_risk_ids) ? $json.existing_risk_ids : [];
let maxNum = 0;
for (const id of existingIds) {
  const m = /^R(\d+)$/i.exec((id || '').toString().trim());
  if (m) {
    const n = parseInt(m[1], 10);
    if (n > maxNum) maxNum = n;
  }
}

const newRisks = Array.isArray($json.new_risks) ? $json.new_risks : [];
const today = new Date().toISOString().slice(0, 10);

return newRisks.map((nr, idx) => {
  const num = maxNum + idx + 1;
  const risk_id = 'R' + String(num).padStart(2, '0');
  return { json: {
    risk_id,
    category: nr.category || '',
    risk_challenge: nr.risk || '',
    impact: nr.impact || '',
    mitigation_strategy: nr.mitigation || '',
    last_updated: today,
    status: 'Open'
  } };
});

