parameters.jsCode:
// Safely parses the Orchestrator's routing JSON and flags malformed output
const raw = $json.output ?? $json.text ?? '';
const cleaned = raw.replace(/```json|```/g, '').trim();
let parsed, valid = true, error = null;
try { parsed = JSON.parse(cleaned); } catch (e) { valid = false; error = e.message; parsed = {}; }
return [{ json: {
  chatInput: $('N2: User Input').first().json.chatInput,
  sessionId: $('N2: User Input').first().json.sessionId,
  source: $('N2: User Input').first().json.source,
  ...parsed,
  _valid: valid,
  _parseError: error
} }];

// M3: Parse Milestone JSON + deterministic risk evaluation
// M2 now only extracts milestone + dependency-task data faithfully (no date
// judgment at all); this node does every date comparison and the at-risk /
// on-track determination in real code, the same way N26 does for the status
// report — comparing a planned end date to today, or checking a 7-day window,
// is exactly the kind of arithmetic that previously made M2 call a milestone
// over a month away "within 7 days," and miss that a dependency task was
// already overdue.

const raw = $json.output ?? $json.text ?? '';
const cleaned = raw.replace(/```json|```/g, '').trim();
let parsed, valid = true, error = null;
try { parsed = JSON.parse(cleaned); } catch (e) { valid = false; error = e.message; parsed = {}; }

if (!valid) {
  return [{ json: { ...parsed, at_risk: [], on_track_count: 0, summary: '', _valid: valid, _parseError: error } }];
}

const todayStr = (typeof $now !== 'undefined' ? $now.toFormat('yyyy-MM-dd') : new Date().toISOString().slice(0, 10));
const todayDate = new Date(`${todayStr}T00:00:00Z`);
const DAY_MS = 24 * 60 * 60 * 1000;

function isDone(status) {
  const s = (status || '').trim().toLowerCase();
  return s === 'done' || s === 'completed';
}
function parseDate(d) {
  if (!d || !/^\d{4}-\d{2}-\d{2}$/.test(d.trim())) return null;
  return new Date(`${d.trim()}T00:00:00Z`);
}

const milestonesIn = Array.isArray(parsed.milestones) ? parsed.milestones : [];
const atRisk = [];

for (const m of milestonesIn) {
  if (!m || !m.milestone_id) continue;
  if (isDone(m.status)) continue; // a completed milestone is never at risk

  const endDate = parseDate(m.planned_end_date);
  const deps = Array.isArray(m.dependency_tasks) ? m.dependency_tasks : [];
  const incompleteDeps = deps.filter((t) => t && !isDone(t.status));
  const overdueDeps = incompleteDeps.filter((t) => {
    const dd = parseDate(t.due_date);
    return dd && dd < todayDate;
  });

  const overdueMilestone = !!(endDate && endDate <= todayDate);
  const daysLeft = endDate ? Math.round((endDate - todayDate) / DAY_MS) : null;
  const impending = !overdueMilestone && daysLeft !== null && daysLeft >= 0 && daysLeft <= 7 && incompleteDeps.length > 0;

  const reasons = [];
  if (overdueMilestone) {
    reasons.push(`Overdue: the planned end date (${m.planned_end_date}) has already passed and status is '${m.status}'.`);
  }
  if (overdueDeps.length) {
    reasons.push(`Dependency task(s) already past due: ${overdueDeps.map((t) => `${t.task_id || '?'} (due ${t.due_date}, status '${t.status}')`).join(', ')}.`);
  }
  if (impending) {
    const stillIncomplete = incompleteDeps.filter((t) => !overdueDeps.includes(t));
    if (stillIncomplete.length) {
      reasons.push(`Impending threat: the planned end date is ${daysLeft} day(s) away, and dependency task(s) are not confirmed done: ${stillIncomplete.map((t) => `${t.task_id || '?'} (${t.status || 'status unknown'})`).join(', ')}.`);
    }
  }

  if (reasons.length === 0) continue;

  const actionTargets = incompleteDeps.length
    ? incompleteDeps.map((t) => t.task_id || '?').join(', ')
    : null;
  const suggestedAction = actionTargets
    ? `Expedite completion of ${actionTargets}.`
    : 'Confirm actual completion and update the milestone status.';

  atRisk.push({
    milestone_id: m.milestone_id,
    milestone_name: m.milestone_name,
    planned_end_date: m.planned_end_date,
    status: m.status,
    reason: reasons.join(' '),
    suggested_action: suggestedAction,
  });
}

const onTrackCount = milestonesIn.length - atRisk.length;
const summary = atRisk.length === 0
  ? 'All milestones on track.'
  : `${atRisk.length} milestone(s) need attention.`;

return [{ json: { ...parsed, at_risk: atRisk, on_track_count: onTrackCount, summary, _valid: valid, _parseError: error } }];

// Turns one multi-intent classification into one item per intent,
// so everything downstream (N9's Switch, each specialist agent)
// keeps working exactly as it already does, unchanged
return $json.routes.map(r => ({ json: { ...$json, route: r } }));

