=Approve or Deny to Append the following New Risks to Risk Register:
⚡{{ $('N21: Build New Risk Rows').all().length }} New risks found:
{{ $('N21: Build New Risk Rows').all().map(i => i.json.risk_challenge + ' (mitigation: ' + i.json.mitigation_strategy + ')').join('\n') }}

parameters.jsCode:
// N21b's approval collapses to one item (one Approve/Deny decision
// covering all new risks). Re-expand back to N21's full list here,
// so N22 gets one item per risk to append, not just one.
return $('N21: Build New Risk Rows').all();

// Shared empty-output guard for Planner/Status/Stakeholder.
// If the agent timed out or returned nothing, swap in a plain
// fallback instead of letting a blank message reach the user.
const raw = ($json.output ?? '').toString();
if (raw.trim() === '') {
  return [{ json: {
    ...$json,
    output: "We're experiencing high volume of requests right now \u2014 please check back in a moment."
  } }];
}
return [{ json: $json }];

// N26: Format Status Report
// N25 now outputs structured JSON (report_scope, answer, tasks[], upcoming_milestones[],
// requested_categories[], sufficient_data, no_actionable_request) instead of writing the
// final human-readable text itself. This node does the counting, category bucketing,
// due-date comparison, and category-scoping filter deterministically in real code, then
// assembles the exact final text.
//
// This is NOT a re-read of Google Sheets/Drive: it only reformats the data N25 already
// retrieved via its Pinecone tool call this same run.

function stripCodeFence(s) {
  const t = s.trim();
  const fence = t.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  return fence ? fence[1] : t;
}

function safeParse(raw) {
  try {
    return JSON.parse(stripCodeFence(raw));
  } catch (e) {
    return null;
  }
}

const raw = ($json.output ?? '').toString();
const data = safeParse(raw);

if (!data) {
  // Malformed/non-JSON agent output — let the existing empty-output guard (N33)
  // handle it the same way it handles a truly empty response.
  return [{ json: { ...$json, output: '' } }];
}

if (data.no_actionable_request) {
  const answer = (data.answer || 'Could you share more details on what you\'d like a status update on?').trim();
  return [{ json: { ...$json, output: `🔍${answer}` } }];
}

const reportScope = data.report_scope || 'All Sprints';
const answer = (data.answer || '').trim();

// --- Which task-board categories did the user actually ask for? ---
// N25 sets this from CATEGORY SCOPING. Empty / missing / containing "all" means every
// category is in scope (a general status check).
const ALL_CATS = ['done', 'in_progress', 'to_do', 'blocked', 'at_risk'];
let requestedCats = Array.isArray(data.requested_categories) ? data.requested_categories : [];
requestedCats = requestedCats.map((c) => (c || '').toString().trim().toLowerCase());
const wantsAll = requestedCats.length === 0 || requestedCats.includes('all');
const scopeSet = new Set(wantsAll ? ALL_CATS : requestedCats.filter((c) => ALL_CATS.includes(c)));
// Guard against a malformed/empty list after filtering (fall back to showing everything
// rather than silently producing an empty report).
if (scopeSet.size === 0) ALL_CATS.forEach((c) => scopeSet.add(c));

// --- Dedup + bucket tasks deterministically ---
const todayStr = (typeof $now !== 'undefined' ? $now.toFormat('yyyy-MM-dd') : new Date().toISOString().slice(0, 10));

const seenTasks = new Map();
for (const t of Array.isArray(data.tasks) ? data.tasks : []) {
  if (!t || !t.task_id) continue;
  if (!seenTasks.has(t.task_id)) seenTasks.set(t.task_id, t);
}

const done = [];
const inProgress = [];
const toDo = [];
const blocked = [];
const atRisk = [];

for (const t of seenTasks.values()) {
  const status = (t.status || '').trim();
  const dueDate = (t.due_date || '').trim(); // expected YYYY-MM-DD

  // Determine the task's TRUE bucket first (independent of what was asked for) —
  // due-date math always runs on every retrieved task, never only on the ones
  // literally marked "Blocked", so at-risk detection works even when N25 pulled in
  // a task for a different reason (e.g. checking "blocked or at risk" together).
  let bucket;
  let entry;
  if (status === 'Blocked') {
    bucket = 'blocked';
    entry = { task_id: t.task_id, task: t.task, reason: t.reason || 'no reason given' };
  } else {
    const isPastDue = dueDate && /^\d{4}-\d{2}-\d{2}$/.test(dueDate) && dueDate < todayStr;
    if (isPastDue && status !== 'Done') {
      bucket = 'at_risk';
      entry = { task_id: t.task_id, task: t.task, reason: `due date ${dueDate} has passed, not done` };
    } else if (status === 'Done') {
      bucket = 'done';
      entry = { task_id: t.task_id, task: t.task };
    } else if (status === 'In Progress') {
      bucket = 'in_progress';
      entry = { task_id: t.task_id, task: t.task };
    } else {
      bucket = 'to_do';
      entry = { task_id: t.task_id, task: t.task };
    }
  }

  // Only keep it in the OUTPUT if its true bucket is actually in scope. A task N25
  // included only so at-risk status could be checked (e.g. a To Do task that turned
  // out not to be overdue) must not leak into a category nobody asked about.
  if (!scopeSet.has(bucket)) continue;

  if (bucket === 'blocked') blocked.push(entry);
  else if (bucket === 'at_risk') atRisk.push(entry);
  else if (bucket === 'done') done.push(entry);
  else if (bucket === 'in_progress') inProgress.push(entry);
  else toDo.push(entry);
}

// --- Dedup milestones ---
const seenMilestones = new Map();
for (const m of Array.isArray(data.upcoming_milestones) ? data.upcoming_milestones : []) {
  if (!m || !m.milestone_id) continue;
  if (!seenMilestones.has(m.milestone_id)) seenMilestones.set(m.milestone_id, m);
}
const milestones = [...seenMilestones.values()];

// --- Health (deterministic) — always reflects the FULL picture, not just what's scoped ---
// Health should never look rosier just because the request narrowed to one category, so
// this stays based on the true blocked/at-risk sets before scope filtering would have run.
// Recompute from the unfiltered seenTasks so a "which tasks are blocked" query still
// reports the real overall health rather than one derived from a partial view.
let trueBlockedCount = 0;
let trueAtRiskCount = 0;
for (const t of seenTasks.values()) {
  const status = (t.status || '').trim();
  const dueDate = (t.due_date || '').trim();
  if (status === 'Blocked') { trueBlockedCount++; continue; }
  const isPastDue = dueDate && /^\d{4}-\d{2}-\d{2}$/.test(dueDate) && dueDate < todayStr;
  if (isPastDue && status !== 'Done') trueAtRiskCount++;
}
let health;
if (trueBlockedCount === 0 && trueAtRiskCount === 0) health = 'Green';
else if (trueBlockedCount > 0) health = 'Red';
else health = 'Amber';

// --- Scope line (part 1) ---
const categories = [
  ['done', 'done', done],
  ['in_progress', 'in progress', inProgress],
  ['to_do', 'to do', toDo],
  ['blocked', 'blocked', blocked],
  ['at_risk', 'at risk', atRisk],
];
const nonEmptyCats = categories.filter(([, , arr]) => arr.length > 0);

let taskClause = '';
if (nonEmptyCats.length === 1) {
  const n = nonEmptyCats[0][2].length;
  taskClause = `${n} task${n === 1 ? '' : 's'} found`;
} else if (nonEmptyCats.length > 1) {
  taskClause = nonEmptyCats.map(([, label, arr]) => `${arr.length} ${label}`).join(', ');
}

const milestoneClause = milestones.length > 0
  ? `${milestones.length} milestone${milestones.length > 1 ? 's' : ''} found`
  : '';

let scopeBody = [taskClause, milestoneClause].filter(Boolean).join(', ');
if (!scopeBody) scopeBody = 'nothing found';

let scopeLine = `🔍Scoped to ${reportScope} — ${scopeBody}.`;
if (answer) {
  scopeLine = `${answer}\n\n${scopeLine}`;
}

// --- Status report (part 2) ---
const lines = [];
if (done.length) lines.push(`Done: ${done.map((t) => `${t.task_id} - ${t.task}`).join(', ')}`);
if (inProgress.length) lines.push(`In progress: ${inProgress.map((t) => `${t.task_id} - ${t.task}`).join(', ')}`);
if (toDo.length) lines.push(`To do: ${toDo.map((t) => `${t.task_id} - ${t.task}`).join(', ')}`);
if (blocked.length) lines.push(`Blocked: ${blocked.map((t) => `${t.task_id} - ${t.task} (${t.reason})`).join(', ')}`);
if (atRisk.length) lines.push(`At risk: ${atRisk.map((t) => `${t.task_id} - ${t.task} (${t.reason})`).join(', ')}`);
if (milestones.length) lines.push(`Upcoming milestones: ${milestones.map((m) => `${m.milestone_id} - ${m.milestone}`).join(', ')}`);

// The header should name what's actually being shown. "Status report" implies the full
// picture, so it's only used for a genuine general check (requested_categories "all").
// A query narrowed to specific categories (e.g. "which tasks are blocked or at risk")
// gets a header built from exactly those categories instead — and overall health, being
// a whole-picture signal nobody asked about here, is only shown on the general-check header.
const CAT_TITLE = { done: 'Done', in_progress: 'In progress', to_do: 'To do', blocked: 'Blocked', at_risk: 'At risk' };
let header;
if (wantsAll) {
  header = `📊Status report for ${reportScope} (overall health: ${health}):`;
} else {
  const labels = ALL_CATS.filter((c) => scopeSet.has(c)).map((c) => CAT_TITLE[c]);
  const labelStr = labels.length <= 1
    ? labels.join('')
    : labels.slice(0, -1).join(', ') + ' & ' + labels[labels.length - 1];
  header = `📊${labelStr} — ${reportScope}:`;
}

const part2 = `${header}\n${lines.join('\n')}`;

const output = `${scopeLine}\n\n${part2}`;

return [{ json: { ...$json, output } }];

// N31: Format Stakeholder Email
// N30 now outputs structured JSON: an LLM-authored subject/progress_summary/next_steps
// (prose is still the agent's job — this is an email, not a data table), plus a "tasks"
// array of real task records it retrieved (task_id/task/status/due_date/reason). This
// node deterministically checks each task's due_date in real code and writes the
// blocker/missed-deadline sentence itself, the same way N26 does for the status report —
// so "are there any blockers" is never answered by the LLM doing date math in its head.

function stripCodeFence(s) {
  const t = s.trim();
  const fence = t.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  return fence ? fence[1] : t;
}

function safeParse(raw) {
  try {
    return JSON.parse(stripCodeFence(raw));
  } catch (e) {
    return null;
  }
}

const raw = ($json.output ?? '').toString();
const data = safeParse(raw);

if (!data) {
  // Malformed/non-JSON agent output — let N33's empty-output guard handle it.
  return [{ json: { ...$json, output: '' } }];
}

if (data.sufficient_data === false) {
  const msg = (data.insufficient_data_message || "There isn't enough tracked data to write this update.").trim();
  return [{ json: { ...$json, output: msg } }];
}

const subject = (data.subject || 'Project Update').trim();
const progressSummary = (data.progress_summary || '').trim();
const nextSteps = (data.next_steps || '').trim();

// --- Dedup + check tasks deterministically ---
const todayStr = (typeof $now !== 'undefined' ? $now.toFormat('yyyy-MM-dd') : new Date().toISOString().slice(0, 10));

const seenTasks = new Map();
for (const t of Array.isArray(data.tasks) ? data.tasks : []) {
  if (!t || !t.task_id) continue;
  if (!seenTasks.has(t.task_id)) seenTasks.set(t.task_id, t);
}

const blocked = [];
const overdue = [];
for (const t of seenTasks.values()) {
  const status = (t.status || '').trim();
  const dueDate = (t.due_date || '').trim();

  if (status === 'Blocked') {
    blocked.push({ task_id: t.task_id, task: t.task, reason: t.reason || 'no reason given' });
    continue;
  }
  const isPastDue = dueDate && /^\d{4}-\d{2}-\d{2}$/.test(dueDate) && dueDate < todayStr;
  if (isPastDue && status !== 'Done') {
    overdue.push({ task_id: t.task_id, task: t.task, due_date: dueDate });
  }
}

// --- Build the blocker/risk sentence deterministically ---
let blockerSentence;
if (blocked.length === 0 && overdue.length === 0) {
  blockerSentence = 'There are no reported blockers or missed deadlines at this time.';
} else {
  const parts = [];
  if (blocked.length) {
    parts.push(
      `${blocked.length > 1 ? 'tasks' : 'task'} ${blocked.map((t) => `${t.task_id} - ${t.task} (${t.reason})`).join(', ')} ${blocked.length > 1 ? 'are' : 'is'} blocked`
    );
  }
  if (overdue.length) {
    parts.push(
      `${overdue.length > 1 ? 'tasks' : 'task'} ${overdue.map((t) => `${t.task_id} - ${t.task} (due ${t.due_date}, not yet done)`).join(', ')} ${overdue.length > 1 ? 'have' : 'has'} missed ${overdue.length > 1 ? 'their' : 'its'} deadline`
    );
  }
  blockerSentence = `However, ${parts.join('; and ')}.`;
}

const bodyParts = [progressSummary, blockerSentence, nextSteps].filter(Boolean);
const body = bodyParts.join(' ');

const output = `📧 *${subject}*\n\nHello,\n\n${body}\n\nBest regards,\nMira`;

return [{ json: { ...$json, output } }];
